import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百七十六章 狮子的吼叫声","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/276第二百七十六章 狮子的吼叫声.md","filePath":"meditation/巴利文大藏经/276第二百七十六章 狮子的吼叫声.md"}'),r={name:"meditation/巴利文大藏经/276第二百七十六章 狮子的吼叫声.md"};function _(n,p,i,s,d,c){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="第二百七十六章-狮子的吼叫声" tabindex="-1">第二百七十六章 狮子的吼叫声 <a class="header-anchor" href="#第二百七十六章-狮子的吼叫声" aria-label="Permalink to &quot;第二百七十六章 狮子的吼叫声&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部22相应78经/狮子经(蕴相应/蕴篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！兽中之王狮子傍晚的时候从栖息的地方走出来，它环顾四周后，就三次大声的吼叫，之后，狮子就准备开始猎杀各种动物。比丘们！任何的飞禽走兽听到狮子的吼叫声，都会感觉到害怕、恐惧，它们都会想办法躲藏起来，它们的内心被狮子的吼声吓的颤抖。居住在洞穴中的动物，它们会躲进洞穴中；生活在水中的动物，它们会潜入水中；居住在树林里的动物，它们有的会爬上大树躲藏，它们有的会躲入密林草丛之中；有翅膀的动物，它们或者飞在空中翱翔，或者站在离地面很高的树枝、岩壁上，避免被狮子伤害。比丘们！即使那些在乡村、城镇、王城里面被坚固的缰绳系住的大象、战马，它们听到狮子的吼叫声后，也会因为害怕、恐惧而奋力的挣脱、扯断缰绳，躲藏到它们认为安全的地方，甚至于一些大象、战马还会被吓的大小便失禁。比丘们！兽中之王狮子对飞禽走兽就有这么大的威慑力，狮子的吼叫声就能让飞禽走兽胆战心惊、惶惶不安。</p><p>比丘们！同样的道理，如来教导世间的众生：「什么是物质事物、物质身体、感受、念想、行为、认识、分别、判断；物质事物、物质身体、感受、念想、行为、认识、分别、判断的生起、形成、起因；物质事物、物质身体、感受、念想、行为、认识、分别、判断的消退、灭尽。」，这些已经受到如来教导的世间众生，不管他们是住在高大华丽宫殿、府院中大权在握、享受各种欲乐的国王、王族贵戚、公卿大臣，还是富可敌国的富翁，一般的平民百姓、贩夫走卒。他们听闻如来的正法后，大部分的人都会害怕、恐惧、内心颤抖。他们会说：「哎呀，还真是这样的，我们是无法永远不死的，我们是无法永远存在的，我们是会生病、衰老、死亡的。我们拥有的财物是无法永远拥有的，我们会失去这些财物，我们拥有的财物会衰败、灭亡、消失。然而我们根本没有去想这个问题，或者我们一直忙于享乐、赚钱、工作等等的事情，还没有意识到我们是会生病、衰老、死亡的，还没有意识到我们最终会离开这个世间，无法永远的长生不死，无法永远的存在。我们还没有意识到我们苦苦经营的国家、事业，挣回来的财物是会失去的，还没有意识到我们拥有的财物是无法永远拥有的，还没有意识到我们会失去这些财物，还没有意识到我们拥有的财物会衰败、灭亡、消失。</p><p>我们好像有一种错觉，有一种可以青春永驻、长生不死的错觉，我们没有生病、衰老、临死的时候，那种青春永驻、长生不死的错觉就更加的严重，当我们生病、衰老、临死的时候，我们好像一下子就回到了现实之中，我们这个时候才会意识到自己是无法永远不死的，才会意识到自己是会生病、衰老、死亡的。一旦意识到我们自己是会生病、衰老、死亡的时候，我们就会害怕，我们就会恐惧，我们的内心就会颤抖。</p><p>我们好像有一种错觉，有一种可以永远拥有财物的错觉，有一种可以永远享乐，永远拥有权力的错觉，我们拥有财物、权力，我们乐在其中的时候，那种可以永远拥有财物、权力，可以永远享乐的错觉就更加的严重。当我们失去财物，我们的财物衰败、灭亡、消失的时候，当我们失去权力，快乐的感受消退、灭尽，无法再享乐的时候，当我们产生烦恼和痛苦的时候，我们好像一下子就回到了现实，我们这个时候才会意识到自己无法永远拥有这些财物，才会意识到自己无法永远的拥有这些权利，才会意识到快乐的感受是会消退、灭尽的，无法永远的享乐。一旦意识到我们无法永远的拥有财物、权力，无法永远的享乐的时候，我们就会害怕，我们就会恐惧，我们的内心就会颤抖。」 比丘们！如来的正法就有这么大的威慑力，如来的正法能够让世间的众生意识到自己所处的现实情况，让他们面对这些让自己胆战心惊、惶惶不安的世间真相、规则，如来的正法就如同兽中之王狮子的吼叫声一样，让这些沉迷于世间贪欲、渴爱之中的众生由于明白事实的真相而内心颤抖、恐惧，进而按如来的正法去修行，由此除灭他们一切的贪欲、渴爱，除灭他们一切的烦恼和痛苦，让他们证悟解脱的果位，让他们从生死轮回中永远的解脱出来，最终达到不生不灭涅槃的境界。</p><p>如来已经开启了解脱的智慧，证悟明白了世间的真相、规则，并用自己实践的修行验证了这些解脱的智慧。如来对世间的众生讲说这些解脱的智慧，受到如来教导的众生，他们明白了原来世间的一切事物是会生起、形成、存续、发展、衰败、灭亡、消失的，是无法永远存在的，是随时在变化的。身体是会生病、衰老、死亡的，拥有的物质事物是会失去的，是会衰败、灭亡、消失的，感受、念想、行为、认识、分别、判断是会消退、灭尽的。有条件就会生起出现，有条件就会灭尽消失。修习八正道（八正道解释，见第十八章）就能逐渐的灭尽一切的烦恼和痛苦，那些世间长寿，长相漂亮、俊美，名声广大，权倾天下，富甲一方的众生，那些寿命普通，长相普通，名声普通，权力普通，财富普通的众生，那些短命，长相丑陋，没有名声，没有权力，没有财富的众生，以及世间一切的众生，他们听闻如来的正法后会害怕，会恐惧，就如同森林里的飞禽走兽听到兽中之王狮子的吼叫声后会害怕、恐惧一样，这些听闻到如来正法的众生他们会认识到：「原来自己是无法永远不死的，原来自己是会生病、衰老、死亡的。原来自己无法永远的拥有财物、权力，原来自己无法永远的享乐。」他们的内心会由此害怕、恐惧，这样他们就能从梦境中苏醒过来，他们就能从永远不死、永远存在、永远拥有、永远不变的错觉中走出来，他们就能明白世间事实的真相，回到现实中来，他们就会按如来的正法去修行，并由此除灭他们自己一切的贪欲、渴爱，除灭他们自己一切的烦恼和痛苦，这样他们就能证悟解脱的果位，他们就能从生死轮回中永远的解脱出来，他们就能最终达到不生不灭涅槃的境界。”</p><p>这时，佛陀说偈言：</p><p>「佛于现证知，</p><p>于人天世间，</p><p>常启解脱慧。</p><p>如是有身灭，</p><p>如是有身生。</p><p>八支之圣道，</p><p>乃灭苦之道。</p><p>形体胜有誉，</p><p>长寿之诸天，</p><p>闻法则战栗，</p><p>似兽见狮子。</p><p>闻如来教言，</p><p>此乃无常身，</p><p>我等超有身。」</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',24)]))}const f=t(r,[["render",_]]);export{m as __pageData,f as default};
